#ifndef MODULE_CONVERTER_ELF32_H
#define MODULE_CONVERTER_ELF32_H

#include <stddef.h>
#include <stdint.h>

/* ISSUE #585: ELF32 field layouts and little-endian byte decoding.  */
#define MODULE_ELF32_IDENT_SIZE                  16UL
#define MODULE_ELF32_HEADER_SIZE                 52UL
#define MODULE_ELF32_PROGRAM_HEADER_SIZE         32UL
#define MODULE_ELF32_SECTION_HEADER_SIZE         40UL
#define MODULE_ELF32_SYMBOL_TABLE_ENTRY_SIZE     16UL

/* These structures hold host-side values after decoding. They are never used
   as overlays for bytes from the file.  */
typedef struct ELF_HEADER_STRUCT
{
    uint8_t     elf_header_id_string[MODULE_ELF32_IDENT_SIZE];
    uint16_t    elf_header_file_type;
    uint16_t    elf_header_machinge_type;
    uint32_t    elf_header_version;
    uint32_t    elf_header_entry_address;
    uint32_t    elf_header_program_header_offset;
    uint32_t    elf_header_section_header_offset;
    uint32_t    elf_header_processor_flags;
    uint16_t    elf_header_size;
    uint16_t    elf_header_program_header_size;
    uint16_t    elf_header_program_header_entries;
    uint16_t    elf_header_section_header_size;
    uint16_t    elf_header_section_header_entries;
    uint16_t    elf_header_section_string_index;
} ELF_HEADER;


typedef struct ELF_PROGRAM_HEADER_STRUCT
{
    uint32_t    elf_program_header_type;
    uint32_t    elf_program_header_offset;
    uint32_t    elf_program_header_virtual_address;
    uint32_t    elf_program_header_physical_address;
    uint32_t    elf_program_header_file_size;
    uint32_t    elf_program_header_memory_size;
    uint32_t    elf_program_header_flags;
    uint32_t    elf_program_header_alignment;
} ELF_PROGRAM_HEADER;


typedef struct ELF_SECTION_HEADER_STRUCT
{
    uint32_t    elf_section_header_name;
    uint32_t    elf_section_header_type;
    uint32_t    elf_section_header_flags;
    uint32_t    elf_section_header_address;
    uint32_t    elf_section_header_offset;
    uint32_t    elf_section_header_size;
    uint32_t    elf_section_header_link;
    uint32_t    elf_section_header_info;
    uint32_t    elf_section_header_alignment;
    uint32_t    elf_section_header_entry_size;
} ELF_SECTION_HEADER;


typedef struct ELF_SYMBOL_TABLE_ENTRY_STRUCT
{
    uint32_t    elf_symbol_table_entry_name;
    uint32_t    elf_symbol_table_entry_address;
    uint32_t    elf_symbol_table_entry_size;
    uint8_t     elf_symbol_table_entry_info;
    uint8_t     elf_symbol_table_entry_other;
    uint16_t    elf_symbol_table_entry_shndx;
} ELF_SYMBOL_TABLE_ENTRY;

/* ISSUE #585: C99-compatible layout checks keep host-side values predictable.
   A failure means a future edit changed a value structure away from the ELF32
   field sizes.  */
typedef char module_elf32_header_size_check[
    (sizeof(ELF_HEADER) == MODULE_ELF32_HEADER_SIZE) ? 1 : -1];
typedef char module_elf32_program_header_size_check[
    (sizeof(ELF_PROGRAM_HEADER) == MODULE_ELF32_PROGRAM_HEADER_SIZE) ? 1 : -1];
typedef char module_elf32_section_header_size_check[
    (sizeof(ELF_SECTION_HEADER) == MODULE_ELF32_SECTION_HEADER_SIZE) ? 1 : -1];
typedef char module_elf32_symbol_table_entry_size_check[
    (sizeof(ELF_SYMBOL_TABLE_ENTRY) == MODULE_ELF32_SYMBOL_TABLE_ENTRY_SIZE) ? 1 : -1];

/* ISSUE #585: decode raw file bytes explicitly; do not cast file data to a
   host structure, because host endianness and alignment may differ.  */
static uint16_t module_elf32_read_u16_le(const uint8_t *bytes)
{

    return((uint16_t)((uint16_t)bytes[0] | ((uint16_t)bytes[1] << 8)));
}

static uint32_t module_elf32_read_u32_le(const uint8_t *bytes)
{

    return(((uint32_t)bytes[0]) |
           ((uint32_t)bytes[1] << 8) |
           ((uint32_t)bytes[2] << 16) |
           ((uint32_t)bytes[3] << 24));
}

static int module_elf32_decode_header(const uint8_t *bytes,
                                      size_t bytes_size,
                                      ELF_HEADER *header)
{

    size_t index;

    if ((bytes == NULL) || (header == NULL) ||
        (bytes_size < MODULE_ELF32_HEADER_SIZE))
    {

        return(1);
    }

    /* Accept the ELF32 little-endian encoding supported by these tools.  */
    if ((bytes[0] != 0x7FU) || (bytes[1] != (uint8_t)'E') ||
        (bytes[2] != (uint8_t)'L') || (bytes[3] != (uint8_t)'F') ||
        (bytes[4] != 1U) || (bytes[5] != 1U) || (bytes[6] != 1U))
    {

        return(1);
    }

    for (index = 0; index < MODULE_ELF32_IDENT_SIZE; index++)
    {

        header -> elf_header_id_string[index] =  bytes[index];
    }

    header -> elf_header_file_type =  module_elf32_read_u16_le(&bytes[16]);
    header -> elf_header_machinge_type =  module_elf32_read_u16_le(&bytes[18]);
    header -> elf_header_version =  module_elf32_read_u32_le(&bytes[20]);
    header -> elf_header_entry_address =  module_elf32_read_u32_le(&bytes[24]);
    header -> elf_header_program_header_offset =  module_elf32_read_u32_le(&bytes[28]);
    header -> elf_header_section_header_offset =  module_elf32_read_u32_le(&bytes[32]);
    header -> elf_header_processor_flags =  module_elf32_read_u32_le(&bytes[36]);
    header -> elf_header_size =  module_elf32_read_u16_le(&bytes[40]);
    header -> elf_header_program_header_size =  module_elf32_read_u16_le(&bytes[42]);
    header -> elf_header_program_header_entries =  module_elf32_read_u16_le(&bytes[44]);
    header -> elf_header_section_header_size =  module_elf32_read_u16_le(&bytes[46]);
    header -> elf_header_section_header_entries =  module_elf32_read_u16_le(&bytes[48]);
    header -> elf_header_section_string_index =  module_elf32_read_u16_le(&bytes[50]);

    if ((header -> elf_header_version != 1U) ||
        (header -> elf_header_size != MODULE_ELF32_HEADER_SIZE) ||
        ((header -> elf_header_program_header_entries != 0U) &&
         (header -> elf_header_program_header_size != MODULE_ELF32_PROGRAM_HEADER_SIZE)) ||
        ((header -> elf_header_section_header_entries != 0U) &&
         (header -> elf_header_section_header_size != MODULE_ELF32_SECTION_HEADER_SIZE)))
    {

        return(1);
    }

    return(0);
}

static int module_elf32_decode_section_header(const uint8_t *bytes,
                                             size_t bytes_size,
                                             ELF_SECTION_HEADER *header)
{

    if ((bytes == NULL) || (header == NULL) ||
        (bytes_size < MODULE_ELF32_SECTION_HEADER_SIZE))
    {

        return(1);
    }

    header -> elf_section_header_name =  module_elf32_read_u32_le(&bytes[0]);
    header -> elf_section_header_type =  module_elf32_read_u32_le(&bytes[4]);
    header -> elf_section_header_flags =  module_elf32_read_u32_le(&bytes[8]);
    header -> elf_section_header_address =  module_elf32_read_u32_le(&bytes[12]);
    header -> elf_section_header_offset =  module_elf32_read_u32_le(&bytes[16]);
    header -> elf_section_header_size =  module_elf32_read_u32_le(&bytes[20]);
    header -> elf_section_header_link =  module_elf32_read_u32_le(&bytes[24]);
    header -> elf_section_header_info =  module_elf32_read_u32_le(&bytes[28]);
    header -> elf_section_header_alignment =  module_elf32_read_u32_le(&bytes[32]);
    header -> elf_section_header_entry_size =  module_elf32_read_u32_le(&bytes[36]);

    return(0);
}

#endif /* MODULE_CONVERTER_ELF32_H */
